import { NestedSubTopic, TopicTest, Question } from '../types';

// Helper to construct error detection question
const createErrorQ = (
  id: string,
  question: string,
  options: string[],
  correctIndex: number,
  explanation: string
): Question => ({
  id,
  question,
  options,
  correctIndex,
  explanation,
});

// Helper to construct fill-in-the-blank question
const createFillQ = (
  id: string,
  question: string,
  options: string[],
  correctIndex: number,
  explanation: string
): Question => ({
  id,
  question,
  options,
  correctIndex,
  explanation,
});

